  $("#workspace-content").innerHTML=hero(t("create_title"),t("create_intro"))+`<form id="create-project-form" class="panel"><label class="field"><span>${t("project_name")}</span><input id="project-name" required value="${esc(app.projectDraft?.project_name||"")}" placeholder="${t("project_placeholder")}"></label><div class="field"><span>${t("defect_classes")}</span><div id="class-editor" class="class-editor">${draftClasses.map(value=>`<div class="class-row"><input class="class-input" required value="${esc(value)}" placeholder="${t("class_placeholder")}"><button class="ghost-button remove-class" type="button">${t("remove")}</button></div>`).join("")}</div><button id="add-class" class="text-button" type="button">+ ${t("add_class")}</button></div><label class="field model-storage-field"><span>${t("model_storage_folder")}</span><input id="model-storage-root" required autocomplete="off" placeholder="${t("model_storage_placeholder")}"><small class="field-help">${t("model_storage_required")}</small></label><div class="notice model-storage-notice">${t("model_storage_only")}</div><div class="form-actions"><button class="primary-button" type="submit">${t("create_project")}</button></div></form>`;
  $("#add-class").onclick=()=>{const row=document.createElement("div");row.className="class-row";row.innerHTML=`<input class="class-input" required placeholder="${t("class_placeholder")}"><button class="ghost-button remove-class" type="button">${t("remove")}</button>`;$("#class-editor").append(row)};
  $("#class-editor").onclick=e=>{if(e.target.classList.contains("remove-class")&&document.querySelectorAll(".class-row").length>1)e.target.closest(".class-row").remove()};
