function labeledBundleForm(target){const initial=target==="initial",formId=initial?"initial-labeled-bundle-form":"maintenance-labeled-bundle-form",inputId=initial?"initial-labeled-bundle-file":"maintenance-labeled-bundle-file",statusId=initial?"initial-labeled-bundle-status":"maintenance-labeled-bundle-status";return `<form id="${formId}" class="panel labeled-bundle-panel"><span class="eyebrow">${t("verified_bundle")}</span><p>${t("verified_bundle_intro")}</p><label class="upload-drop"><input id="${inputId}" type="file" accept="application/zip,.zip" required><strong>${t("choose_bundle")}</strong><span>${t("bundle_confirmation")}</span></label><div id="${statusId}" class="notice" hidden></div><div class="form-actions"><button class="primary-button" type="submit">${t("verified_bundle")}</button></div></form>`}
