function bindImport(){const input=$("#image-files");input.onchange=()=>{$("#file-summary").textContent=`${input.files.length} ${t("images")}`};$("#import-form").onsubmit=importImages;$("#initial-labeled-bundle-form").onsubmit=event=>importLabeledBundle(event,"initial")}
async function importImages(event){event.preventDefault();const files=[...$("#image-files").files];if(!files.length)return;let dataset=app.dataset;try{if(!dataset){const created=await api("/api/tool/run",{method:"POST",body:JSON.stringify({tool:"import_dataset",arguments:{project_id:app.project.project_id,name:$("#dataset-name").value.trim(),role:$("#dataset-role").value},actor_type:"human",actor_id:"local_engineer",confirmed:false})});dataset=created.result.dataset}const box=$("#upload-progress");box.hidden=false;for(let i=0;i<files.length;i++){const file=files[i];box.querySelector("small").textContent=`${t("uploading")} ${i+1}/${files.length}: ${file.name}`;box.querySelector("span").style.width=`${(i/files.length)*100}%`;await fetch(`/api/datasets/upload?dataset_id=${encodeURIComponent(dataset.dataset_id)}&filename=${encodeURIComponent(file.name)}`,{method:"POST",headers:{"Content-Type":file.type||"application/octet-stream"},body:file}).then(async response=>{const data=await response.json();if(!response.ok||data.ok===false)throw new Error(data.error||`HTTP ${response.status}`)})}box.querySelector("span").style.width="100%";toast(`${files.length} ${t("images")}`);await refresh(app.project.project_id)}catch(error){toast(error.message);await refresh(app.project.project_id)}}

function maintenanceImportPanel(){const dataset=app.activeBatch?.dataset;return hero(t("maintenance_import_title"),t("maintenance_intro"))+labeledBundleForm("maintenance")+`<div class="import-divider"><span>${t("manual_import")}</span></div><form id="maintenance-import-form" class="panel"><div class="job-details"><div><small>${t("maintenance_batch_name")}</small><strong>${esc(app.activeBatch?.name||"—")}</strong></div><div><small>${t("batch_status")}</small><strong>${esc(app.activeBatch?.state||"—")}</strong></div></div><label class="field"><span>${t("maintenance_dataset_name")}</span><input id="maintenance-dataset-name" required value="${esc(dataset?.name||`${app.activeBatch?.name||"maintenance"}-images`)}" placeholder="${t("maintenance_dataset_placeholder")}" ${dataset?"disabled":""}></label><label class="upload-drop"><input id="maintenance-image-files" type="file" accept="image/jpeg,image/png,.jpg,.jpeg,.png" multiple required><strong>${t("choose_images")}</strong><span id="maintenance-file-summary">${t("choose_hint")}</span></label><div id="maintenance-upload-progress" hidden><div class="progress"><span style="width:0"></span></div><small></small></div><div class="form-actions"><button class="primary-button" type="submit">${dataset?t("choose_images"):t("import_images")}</button></div></form>`}
function bindMaintenanceImport(){const input=$("#maintenance-image-files");input.onchange=()=>{$("#maintenance-file-summary").textContent=`${input.files.length} ${t("images")}`};$("#maintenance-import-form").onsubmit=importMaintenanceImages;$("#maintenance-labeled-bundle-form").onsubmit=event=>importLabeledBundle(event,"maintenance")}
