function importLabeledBundle(event,target){event.preventDefault();const input=$(target==="initial"?"#initial-labeled-bundle-file":"#maintenance-labeled-bundle-file"),file=input.files[0];if(!file)return;showConfirm(t("verified_bundle"),t("bundle_confirmation"),()=>uploadLabeledBundle(target,file))}
async function uploadLabeledBundle(target,file){const status=$(target==="initial"?"#initial-labeled-bundle-status":"#maintenance-labeled-bundle-status");status.hidden=false;status.className="notice";status.textContent=t("bundle_importing");const identity=target==="initial"?`project_id=${encodeURIComponent(app.project.project_id)}`:`batch_id=${encodeURIComponent(app.activeBatch.batch_id)}`;try{const response=await fetch(`/api/labeled-bundles/import?target=${target}&${identity}&confirmed=true`,{method:"POST",headers:{"Content-Type":"application/zip"},body:file});const data=await response.json();if(!response.ok||data.ok===false)throw new Error(data.error||`HTTP ${response.status}`);status.className="notice success";status.textContent=`${t("bundle_imported")} · ${data.result.image_count} ${t("images")}`;toast(t("bundle_imported"));await refresh(app.project.project_id)}catch(error){status.className="notice error";status.textContent=error.message;toast(error.message)}}

function renderAnnotation(){
  const maintenance=app.dataset?.role==="maintenance";
  $("#task-title").textContent=t(maintenance?"maintenance_annotate_title":"annotate_title");
  if(!app.images.length){if(maintenance){$("#workspace-content").innerHTML=maintenanceImportPanel();bindMaintenanceImport()}else{$("#workspace-content").innerHTML=importPanel();bindImport()}return}
  const image=app.images[app.imageIndex];const labeled=app.images.filter(i=>i.annotation_status==="complete").length;
  $("#workspace-content").innerHTML=hero(t(maintenance?"maintenance_annotate_title":"annotate_title"),t(maintenance?"maintenance_annotate_intro":"annotate_intro"))+`<div class="stat-grid"><div class="stat"><strong>${app.images.length}</strong><small>${t("images")}</small></div><div class="stat"><strong>${labeled}</strong><small>${t("labeled")}</small></div><div class="stat"><strong>${app.images.length-labeled}</strong><small>${t("unlabeled")}</small></div></div><section class="annotation-layout"><div><div class="image-stage"><img src="/api/images/content?image_id=${encodeURIComponent(image.image_id)}" alt="${esc(image.filename)}"></div><div class="image-meta"><span>${esc(image.filename)}</span><span>${image.width||"?"} × ${image.height||"?"}</span></div></div><form id="annotation-form" class="panel"><span class="eyebrow">${t("defect_classes")}</span><div class="label-list">${app.project.classes.map(c=>`<label class="label-option"><input class="defect-check" type="checkbox" value="${esc(c.class_id)}" ${image.class_ids.includes(c.class_id)?"checked":""}><span>${esc(c.display_name)}</span></label>`).join("")}<label class="label-option no-defect"><input id="no-defect" type="checkbox" ${image.no_defect?"checked":""}><span>${t("no_defect")}</span></label></div><div class="annotation-nav"><button id="prev-image" class="ghost-button" type="button" ${app.imageIndex===0?"disabled":""}>${t("previous")}</button><span class="counter">${app.imageIndex+1} / ${app.images.length}</span><button class="primary-button" type="submit">${t("save_next")}</button></div></form></section><section class="panel"><div class="section-row"><div><h4>${t("validate")}</h4><small class="counter">${labeled}/${app.images.length} ${t("labeled")}</small></div><button id="validate-dataset" class="ghost-button" type="button">${t("validate")}</button></div><div id="validation-result"></div></section>`;
  const noDefect=$("#no-defect"),checks=[...document.querySelectorAll(".defect-check")];noDefect.onchange=()=>{if(noDefect.checked)checks.forEach(c=>c.checked=false)};checks.forEach(c=>c.onchange=()=>{if(c.checked)noDefect.checked=false});
  $("#prev-image").onclick=()=>{app.imageIndex--;renderWorkspace()};$("#annotation-form").onsubmit=saveAnnotation;$("#validate-dataset").onclick=validateDataset;if(app.lastReport)renderValidationReport(app.lastReport);
}
async function saveAnnotation(event){event.preventDefault();const image=app.images[app.imageIndex];const classIds=[...document.querySelectorAll(".defect-check:checked")].map(c=>c.value);const noDefect=$("#no-defect").checked;if(!noDefect&&!classIds.length){toast(t("select_one"));return}try{await api("/api/annotations/save",{method:"POST",body:JSON.stringify({image_id:image.image_id,class_ids:classIds,no_defect:noDefect})});toast(t("saved"));if(app.imageIndex<app.images.length-1)app.imageIndex++;await refresh(app.project.project_id)}catch(error){toast(error.message)}}
async function validateDataset(){try{const data=await api("/api/datasets/validate",{method:"POST",body:JSON.stringify({dataset_id:app.dataset.dataset_id})});app.lastReport=data.report;if(data.report.valid){toast(t("validation_passed"));await refresh(app.project.project_id)}else renderValidationReport(data.report)}catch(error){toast(error.message)}}
