function earlyHoldPanel(noEligible=false){return `<section class="panel"><div class="notice">${noEligible?t("no_eligible_failure"):t("hold_before_challenger_intro")}</div><label class="field"><span>${t("early_hold_reason")}</span><textarea id="early-hold-reason" required placeholder="${t("early_hold_reason_placeholder")}"></textarea></label><div class="notice">${noEligible?t("early_hold_confirmation"):t("hold_before_challenger_confirmation")}</div><div class="form-actions"><button id="record-early-hold" class="primary-button" type="button">${t("hold_without_challenger")}</button></div></section>`}
function challengerJobPanel(version){if(!version)return "";const job=app.challengerJobs[0];if(!job){if(!version.eligible_slice_count)return earlyHoldPanel(true);return `<section class="panel"><h4>${t("challenger_job_title")}</h4><p>${t("challenger_job_intro")}</p><div class="notice">${t("create_challenger_confirmation")}</div><div class="form-actions"><button id="create-challenger-job" class="primary-button" type="button">${t("create_challenger_job")}</button></div></section>${earlyHoldPanel(false)}`}const p=job.pool_counts||{},run=app.challengerRuns[0];let action=`<div class="notice">${t("start_challenger_confirmation")}</div><div class="form-actions"><button id="start-challenger" class="primary-button" type="button">${t("start_challenger")}</button></div>`;if(job.status==="registered")action=`<div class="notice success">✓ ${t("challenger_registered")}</div>`;else if(run&&run.status==="result_verified")action=`<div class="notice success">✓ ${t("challenger_result_verified")}</div><div class="form-actions"><button id="register-challenger" class="primary-button" type="button">${t("register_challenger")}</button></div>`;else if(run&&activeTraining(run))action=challengerProgress(run);else if(run)action=`<div class="notice error">${esc(run.error_message||run.status)}</div><div class="form-actions"><button id="start-challenger" class="primary-button" type="button">${t("start_challenger")}</button></div>`;return `<section class="panel"><div class="notice success">✓ ${t("challenger_job_ready")}</div><p>${t("challenger_job_ready_intro")}</p><div class="stat-grid"><div class="stat"><strong>${p.failure_member_records_available}</strong><small>${t("failure_pool")}</small></div><div class="stat"><strong>${p.remaining_new_images_available}</strong><small>${t("remaining_pool")}</small></div><div class="stat"><strong>${p.history_replay_images_available}</strong><small>${t("history_pool")}</small></div><div class="stat"><strong>160 / 160 / 320</strong><small>${t("fixed_draws")}</small></div></div><div class="job-details"><div><small>ID</small><strong>${esc(job.job_id)}</strong></div><div><small>${t("parent_champion")}</small><strong>${esc(job.parent_champion_model_id)}</strong></div><div><small>${t("profile")}</small><strong>${esc(job.training_profile_id)}</strong></div><div><small>${t("bundle_size")}</small><strong>${formatBytes(job.bundle_size_bytes)}</strong></div><div><small>${t("bundle_hash")}</small><code>${esc(job.bundle_sha256)}</code></div></div><div class="form-actions"><a class="primary-button download-link" href="/api/challenger/jobs/download?job_id=${encodeURIComponent(job.job_id)}">${t("download_challenger")}</a></div>${action}</section>`}
function evaluationProgress(run){const p=run.progress||{},percent=Math.max(0,Math.min(100,Number(p.percent||0))),logs=(app.evaluationEvents||[]).filter(event=>event.kind==="log").slice(-20);return `<section class="panel"><div class="section-row"><div><h4>${t("evaluation_progress")}</h4><small class="counter">${esc(run.status)}</small></div>${gpuQueueControl(run,"cancel-evaluation",t("cancel_evaluation"))}</div><div class="progress training-progress"><span style="width:${percent}%"></span></div><div class="training-facts"><span>${t("selected_gpus")}: GPU ${(run.gpu_devices||[])[0]??"—"}</span><span>${t("stage")}: ${esc(p.stage||"—")}</span><span>${esc(p.images_completed||0)} / ${esc(p.images_total||"—")} ${t("images")}</span></div>${run.error_message?`<div class="notice error">${esc(run.error_message)}</div>`:""}<h4 class="log-title">${t("worker_log")}</h4><div class="worker-log">${logs.length?logs.map(event=>`<div><time>${esc(new Date(event.created_at).toLocaleTimeString())}</time>${esc(event.payload.message||JSON.stringify(event.payload))}</div>`).join(""):`<span>${t("awaiting_worker")}</span>`}</div></section>`}
async function createEvaluationJob(){const select=$("#evaluation-inbox-file");if(!select?.value){toast(t("evaluation_inbox_empty"));return}try{await api("/api/tool/run",{method:"POST",body:JSON.stringify({tool:"create_model_evaluation_job",arguments:{batch_id:app.activeBatch.batch_id,inbox_filename:select.value},actor_type:"human",actor_id:"local_engineer",confirmed:true})});toast(t("create_evaluation_job"));await refresh(app.project.project_id)}catch(error){toast(error.message)}}
