async function cancelEvaluation(){try{await api("/api/tool/run",{method:"POST",body:JSON.stringify({tool:"cancel_model_evaluation",arguments:{run_id:app.evaluationRuns[0].run_id},actor_type:"human",actor_id:"local_engineer",confirmed:true})});toast(t("cancel_evaluation"));await refresh(app.project.project_id)}catch(error){toast(error.message)}}
function metricPercent(value){return `${(Number(value||0)*100).toFixed(1)}%`}
function evidenceSplitCard(key,label){const split=app.evidence?.metrics?.splits?.[key];if(!split)return "";const c=split.champion,h=split.challenger,d=split.delta,tr=split.paired_transitions;const map=c.macro_map===undefined?"":`<div class="stat"><strong>${metricPercent(c.macro_map)} → ${metricPercent(h.macro_map)}</strong><small>${t("macro_map")} · Δ ${Number(d.macro_map).toFixed(3)}</small></div>`;return `<section class="panel"><h4>${esc(label)}</h4><div class="stat-grid">${map}<div class="stat"><strong>${metricPercent(c.macro_f1)} → ${metricPercent(h.macro_f1)}</strong><small>${t("macro_f1")} · Δ ${Number(d.macro_f1).toFixed(3)}</small></div><div class="stat"><strong>${metricPercent(c.micro_f1)} → ${metricPercent(h.micro_f1)}</strong><small>${t("micro_f1")} · Δ ${Number(d.micro_f1).toFixed(3)}</small></div><div class="stat"><strong>${metricPercent(c.exact_match_accuracy)} → ${metricPercent(h.exact_match_accuracy)}</strong><small>${t("exact_match")}</small></div><div class="stat"><strong>${c.false_positive_count}/${c.false_negative_count} → ${h.false_positive_count}/${h.false_negative_count}</strong><small>${t("false_positives")} / ${t("false_negatives")}</small></div></div><div class="job-details"><div><small>${t("champion_only_correct")}</small><strong>${tr.champion_only_correct}</strong></div><div><small>${t("challenger_only_correct")}</small><strong>${tr.challenger_only_correct}</strong></div></div></section>`}
function evidencePanel(){if(!app.evidence)return "";const metrics=app.evidence.metrics||{},current=metrics.current_gate||"current_gate",history=metrics.historical_gates||[],core=metrics.core_safety||metrics.splits?.core_safety,cohorts=metrics.cohorts||[];const cards=evidenceSplitCard(current,`${t("current_gate")} · ${current}`)+(core?evidenceSplitCard("core_safety",t("historical_gates")):history.map(key=>evidenceSplitCard(key,`${t("historical_gates")} · ${key}`)).join(""));const cohortList=cohorts.length?`<div class="notice">${t("gate_history")}: ${cohorts.map(item=>esc(item.cohort_key||item.gate_key||item.name||"—")).join(" · ")}</div>`:"";return `${hero(t("evidence_title"),t("evidence_intro"))}<div class="notice success">✓ ${t("no_automatic_decision")}</div>${cards}${cohortList}<section class="panel"><h4>${t("final_decision")}</h4><label class="field"><span>${t("final_decision")}</span><select id="final-decision"><option value="">—</option><option value="retain">${t("hold")}</option><option value="promote">${t("deploy")}</option></select></label><label class="field"><span>${t("decision_reason")}</span><textarea id="decision-reason" required placeholder="${t("decision_reason_placeholder")}"></textarea></label><div class="notice">${t("decision_confirmation")}</div><div class="form-actions"><button id="record-decision" class="primary-button" type="button">${t("final_decision")}</button></div></section>`}
function roundCompletionPanel(){const completion=app.workflow?.round_completion;if(!completion)return "";return `<section class="panel"><div class="notice success">✓ ${t("round_completed")}</div><p>${t("round_completed_intro")}</p><div class="job-details"><div><small>${t("current_gate")}</small><strong>${completion.current_gate_images||completion.current_gate_count||"—"}</strong></div><div><small>${t("historical_gates")}</small><strong>${completion.cumulative_core_safety_images||completion.core_safety_count||"—"}</strong></div></div></section>`}
async function recordFinalDecision(){const decision=$("#final-decision").value,reason=$("#decision-reason").value.trim();if(!decision){toast(t("final_decision"));return}if(!reason){toast(t("decision_reason"));return}try{await api("/api/tool/run",{method:"POST",body:JSON.stringify({tool:"record_deployment_decision",arguments:{batch_id:app.activeBatch.batch_id,decision,reason},actor_type:"human",actor_id:"local_engineer",confirmed:true})});toast(t(decision==="promote"?"deploy":"hold"));await refresh(app.project.project_id)}catch(error){toast(error.message)}}
async function recordEarlyHold(){const reason=$("#early-hold-reason")?.value.trim();if(!reason){toast(t("early_hold_reason"));return}try{await api("/api/tool/run",{method:"POST",body:JSON.stringify({tool:"record_deployment_decision",arguments:{batch_id:app.activeBatch.batch_id,decision:"hold",reason},actor_type:"human",actor_id:"local_engineer",confirmed:true})});toast(t("hold_without_challenger"));await refresh(app.project.project_id)}catch(error){toast(error.message)}}
function gateCountDetails(job){const counts=job.split_counts||{};return `<div class="job-details">${Object.entries(counts).map(([key,count])=>`<div><small>${esc(key)}</small><strong>${count}</strong></div>`).join("")}</div>`}
function renderChallengerTrained(model){const challenger=app.models.find(item=>item.role==="challenger"),job=app.evaluationJobs[0],run=app.evaluationRuns[0];$("#task-title").textContent=app.evidence?t("evidence_title"):t("evaluation_title");let evaluation="";if(!job){const options=app.evaluationInbox.map(file=>`<option value="${esc(file.name)}">${esc(file.name)} · ${formatBytes(file.size_bytes)}</option>`).join("");const history=app.evaluationGates.filter(gate=>gate.status==="active").map(gate=>`${gate.gate_key} (${gate.image_count})`).join(" · ");evaluation=`<section class="panel"><h4>${t("evaluation_inbox")}</h4>${history?`<div class="notice success">${t("gate_history")}: ${esc(history)}</div>`:""}${options?`<label class="field"><span>${t("evaluation_inbox")}</span><select id="evaluation-inbox-file">${options}</select></label><div class="notice">${t("create_evaluation_confirmation")}</div><div class="form-actions"><button id="create-evaluation-job" class="primary-button" type="button">${t("create_evaluation_job")}</button></div>`:`<div class="notice">${t("evaluation_inbox_empty")}</div>`}</section>`}else if(app.evidence)evaluation=evidencePanel();else if(run&&activeTraining(run))evaluation=evaluationProgress(run);else{let action=`<div class="notice">${t("start_evaluation_confirmation")}</div><div class="form-actions"><button id="start-evaluation" class="primary-button" type="button">${t("start_evaluation")}</button></div>`;if(run&&run.status==="failed")action=`<div class="notice error">${esc(run.error_message||run.status)}</div>${action}`;evaluation=`<section class="panel"><div class="notice success">✓ ${esc(job.job_id)}</div>${gateCountDetails(job)}${action}</section>`}$("#workspace-content").innerHTML=(app.evidence?"":hero(t("evaluation_title"),t("evaluation_intro")))+championCard(model)+(challenger?`<section class="panel"><div class="notice success">✓ ${t("challenger_registered")}</div><div class="job-details"><div><small>${t("model_id")}</small><strong>${esc(challenger.model_id)}</strong></div><div><small>${t("checkpoint_hash")}</small><code>${esc(challenger.checkpoint_sha256)}</code></div></div></section>`:"")+evaluation}
document.addEventListener("click",event=>{const id=event.target?.id;if(id==="start-challenger")showConfirm(t("start_challenger"),t("start_challenger_confirmation"),startChallengerTraining);if(id==="cancel-challenger")showConfirm(t("cancel_challenger"),t("cancel_challenger_confirmation"),cancelChallengerTraining);if(id==="register-challenger")showConfirm(t("register_challenger"),t("register_challenger_confirmation"),registerChallenger);if(id==="create-evaluation-job")showConfirm(t("create_evaluation_job"),t("create_evaluation_confirmation"),createEvaluationJob);if(id==="start-evaluation")showConfirm(t("start_evaluation"),t("start_evaluation_confirmation"),startEvaluation);if(id==="cancel-evaluation")showConfirm(t("cancel_evaluation"),t("cancel_evaluation_confirmation"),cancelEvaluation);if(id==="record-decision")showConfirm(t("final_decision"),t("decision_confirmation"),recordFinalDecision);if(id==="record-early-hold"){const eligible=app.failureReview?.frozen_version?.eligible_slice_count||0;showConfirm(t("hold_without_challenger"),t(eligible?"hold_before_challenger_confirmation":"early_hold_confirmation"),recordEarlyHold)}});
document.addEventListener("click",event=>{if(event.target?.id==="cancel-queued-task")showConfirm(t("cancel_queued_task"),t("cancel_queued_confirmation"),cancelQueuedTask)});

function historyDescription(item){const d=item.data;if(item.kind==="audit")return {title:d.tool_name,body:`${d.from_state||"—"} → ${d.to_state||"—"}`,code:d.event_sha256?.slice(0,16)};if(item.kind==="message")return {title:d.role==="user"?(app.lang==="zh"?"工程师消息":"Engineer message"):(app.lang==="zh"?"Agent 消息":"Agent message"),body:d.content,code:`${d.provider} · ${d.model}`};if(item.kind==="tool_run")return {title:d.tool_name,body:`status: ${d.status}`,code:d.run_id};if(item.kind==="approval")return {title:d.tool_name,body:`status: ${d.status}${d.resolved_by?` · ${d.resolved_by}`:""}`,code:d.pending_id};if(item.kind==="label_version")return {title:`${t("label_version")} ${d.version_number}`,body:`${d.dataset_name} · ${d.image_count} ${t("images")}`,code:d.labels_sha256?.slice(0,16)};if(item.kind==="maintenance_batch")return {title:`${t("maintenance_batches_count")} · ${d.name}`,body:d.state,code:d.batch_id};if(item.kind==="training_job")return {title:`${t("training_jobs_count")} · ${d.job_id}`,body:`${d.status} · ${d.training_profile_id}`,code:d.bundle_sha256?.slice(0,16)};if(item.kind==="training_run")return {title:`${t("training_runs_count")} · ${d.run_id}`,body:`${d.status} · GPU ${(d.gpu_devices||[]).join(",")||"—"}`,code:d.result_bundle_sha256?.slice(0,16)};if(item.kind==="model")return {title:`${t("models_count")} · ${d.model_id}`,body:`${d.role} · ${d.training_profile_id}`,code:d.checkpoint_sha256?.slice(0,16)};if(item.kind==="screening_job")return {title:`${t("screening_jobs_count")} · ${d.job_id}`,body:`${d.status} · ${d.discovery_profile_id}`,code:d.bundle_sha256?.slice(0,16)};if(item.kind==="screening_run")return {title:`${t("screening_runs_count")} · ${d.job_id||d.run_id}`,body:`${d.status} · GPU ${(d.gpu_devices||[]).join(",")||"—"}`,code:d.result_bundle_sha256?.slice(0,16)};if(item.kind==="failure_slice")return {title:`${t("failure_slices_count")} · ${d.class_id} ${d.error_type}`,body:`${t("support")}: ${d.support} · ${d.status}`,code:d.slice_id};if(item.kind==="failure_review")return {title:`${t("failure_reviews_count")} · ${d.review_version_id}`,body:`${t("eligible_slices")}: ${d.eligible_slice_count} · ${t("retained_images")}: ${d.retained_unique_images}`,code:d.review_sha256?.slice(0,16)};if(item.kind==="challenger_job")return {title:`${t("challenger_jobs_count")} · ${d.job_id}`,body:`${d.status} · ${d.training_profile_id}`,code:d.bundle_sha256?.slice(0,16)};if(item.kind==="challenger_run")return {title:`${t("challenger_runs_count")} · ${d.run_id}`,body:`${d.status} · GPU ${(d.gpu_devices||[]).join(",")||"—"}`,code:d.result_bundle_sha256?.slice(0,16)};return {title:item.kind,body:"",code:""}}
async function renderHistory(){$("#task-title").textContent=t("history_title");$("#workspace-content").innerHTML=hero(t("history_title"),t("history_intro"))+`<div class="empty">Loading…</div>`;if(!app.project){$("#workspace-content").innerHTML=hero(t("history_title"),t("history_intro"))+`<div class="empty">${t("history_empty")}</div>`;return}try{const history=(await api(`/api/project/history?project_id=${encodeURIComponent(app.project.project_id)}`)).history;const c=history.counts;const cards=[[c.audit_events,t("audit_events")],[c.messages,t("messages_count")],[c.tool_runs,t("tool_runs_count")],[c.approvals,t("approvals_count")],[c.label_versions,t("label_versions_count")],[c.maintenance_batches||0,t("maintenance_batches_count")],[c.training_jobs||0,t("training_jobs_count")],[c.training_runs||0,t("training_runs_count")],[c.screening_jobs||0,t("screening_jobs_count")],[c.screening_runs||0,t("screening_runs_count")],[c.failure_slices||0,t("failure_slices_count")],[c.failure_reviews||0,t("failure_reviews_count")],[c.challenger_jobs||0,t("challenger_jobs_count")],[c.challenger_runs||0,t("challenger_runs_count")],[c.evaluation_gates||0,t("evaluation_gates_count")],[c.models||0,t("models_count")]];$("#workspace-content").innerHTML=hero(t("history_title"),t("history_intro"))+modelStorageCard()+`<div class="history-summary">${cards.map(([n,label])=>`<div class="stat"><strong>${n}</strong><small>${label}</small></div>`).join("")}</div><div class="timeline">${history.timeline.length?history.timeline.map(item=>{const view=historyDescription(item);return `<article class="timeline-item"><div class="timeline-at">${esc(new Date(item.at).toLocaleString(app.lang==="zh"?"zh-CN":"en-US"))}<span class="timeline-kind">${esc(item.kind)}</span></div><div class="timeline-main"><strong>${esc(view.title)}</strong><p>${esc(view.body)}</p>${view.code?`<code>${esc(view.code)}</code>`:""}</div></article>`}).join(""):`<div class="empty">${t("history_empty")}</div>`}</div>`}catch(error){$("#workspace-content").innerHTML=`<div class="notice error">${esc(error.message)}</div>`}}
function renderWorkspace(){if(app.view==="history"){clearTimeout(app.trainingPoll);renderHistory();return}if(!app.project)renderCreate();else if(app.project.state==="PROJECT_CREATED")renderTaxonomy();else if(app.project.state==="TAXONOMY_CONFIRMED"){$("#task-title").textContent=t("import_title");$("#workspace-content").innerHTML=importPanel();bindImport()}else if(app.project.state==="DATA_IMPORTED")renderAnnotation();else if(app.project.state==="DATA_VALIDATED")renderValidated();else if(app.project.state==="INITIAL_TRAINING_READY")renderTrainingReady();else if(["CHAMPION_READY","SCREENING_READY"].includes(app.project.state))renderChampion();else{$("#task-title").textContent=app.project.state;$("#workspace-content").innerHTML=`<div class="empty">${t("phase_next")}</div>`}}

function agentReply(text){const value=text.toLowerCase();if(value.includes("框")||value.includes("box")||value.includes("bbox"))return app.lang==="zh"?"当前任务输出的是整张图片包含哪些缺陷，而不是缺陷位置。因此采用图像级多标签，避免绘制 BBox；模型精度也必须按图像级指标评价。":"This task predicts which defects occur in an image, not their coordinates. Image-level multi-label annotation therefore avoids boxes, and evaluation must remain image-level.";if(value.includes("上传")||value.includes("privacy")||value.includes("upload"))return app.lang==="zh"?"不会上传到外部服务。图片保存在本应用显示的项目目录，标签和审计记录保存在本机数据库。":"No external upload occurs. Images stay in the project directory shown by this application, while labels and audit records stay in the local database.";const state=app.project?.state||"EMPTY";const replies={EMPTY:app.lang==="zh"?"先创建项目，并输入工程师希望识别的缺陷类别。":"Create a project and enter the defect classes the engineer wants to recognize.",PROJECT_CREATED:app.lang==="zh"?"请核对并人工确认类别。确认后才允许导入数据。":"Review and explicitly confirm the taxonomy before importing data.",TAXONOMY_CONFIRMED:app.lang==="zh"?"创建初始训练数据集并选择本地 JPEG/PNG 图片。":"Create the initial training dataset and choose local JPEG/PNG images.",DATA_IMPORTED:app.lang==="zh"?"逐张选择一个或多个缺陷类别；没有缺陷时只选 No defect。全部完成后运行数据检查。":"Select one or more defect classes for each image, or No defect alone, then run deterministic checks.",DATA_VALIDATED:app.lang==="zh"?"数据已经冻结。请先人工确认生成不可变 Initial Champion 训练任务。":"Data is frozen. An engineer can now confirm creation of the immutable Initial Champion job.",INITIAL_TRAINING_READY:app.lang==="zh"?"训练任务已准备。请人工确认启动单 GPU Worker；结果校验通过后还需再次确认才能注册 Champion。":"The immutable job is ready. Confirm the single-GPU Worker start; after result verification, confirm again to register the Champion.",CHAMPION_READY:app.lang==="zh"?"Initial Champion 已注册，可以继续准备筛查流程。":"The Initial Champion is registered; screening preparation can continue."};return replies[state]||t("empty_agent")}
function addMessage(role,text){app.messages.push({role,text});renderAgent()}
function renderAgent(){if(!app.messages.length)app.messages=[{role:"agent",text:t("empty_agent")}];const status=$("#llm-status");status.textContent=app.llm.verified?`${t("llm_verified")} · ${app.llm.model}`:app.llm.configured?`${t("connection_untested")} · ${app.llm.model}`:t("llm_disabled");status.className=app.llm.verified?"llm-online":"llm-offline";$("#agent-messages").innerHTML=app.messages.map(m=>`<div class="agent-message ${m.role==="user"?"user":""}"><b>${m.role==="user"?(app.lang==="zh"?"工程师":"Engineer"):t("assistant")}</b>${esc(m.text)}</div>`).join("");const suggestions=[t("ask_data"),t("ask_labels"),t("ask_privacy")];$("#agent-suggestions").innerHTML=suggestions.map(s=>`<button class="ghost-button" type="button">${esc(s)}</button>`).join("");$("#agent-suggestions").querySelectorAll("button").forEach(b=>b.onclick=()=>submitAgentMessage(b.textContent));$("#agent-messages").scrollTop=$("#agent-messages").scrollHeight}
function render(){renderShell();renderWorkspace();renderAgent()}

$("#confirm-dialog").addEventListener("close",()=>{const approved=$("#confirm-dialog").returnValue==="default";if(app.pendingAgentId){resolveAgentConfirmation(app.pendingAgentId,approved);app.pendingAgentId=null}else if(approved&&app.pendingConfirm)app.pendingConfirm();app.pendingConfirm=null});
$("#delete-project-name").oninput=()=>{$("#delete-project-submit").disabled=$("#delete-project-name").value!==app.pendingProjectDelete?.name};
$("#delete-project-cancel").onclick=()=>{$("#delete-project-dialog").close();app.pendingProjectDelete=null};
$("#delete-project-form").onsubmit=deleteProject;
function setAdvancedOpen(open){if(open)setWorkflowOpen(false);const workspace=$("#advanced-workspace");workspace.classList.toggle("open",open);workspace.setAttribute("aria-hidden",String(!open));$("#advanced-button").setAttribute("aria-expanded",String(open));if(open)$("#workspace-close").focus()}
function setWorkflowOpen(open){if(open)setAdvancedOpen(false);const drawer=$("#workflow-drawer");drawer.classList.toggle("open",open);drawer.setAttribute("aria-hidden",String(!open));$("#workflow-settings-button").setAttribute("aria-expanded",String(open));if(open)$("#workflow-close").focus()}
$("#advanced-button").onclick=()=>setAdvancedOpen(!$("#advanced-workspace").classList.contains("open"));
$("#workspace-close").onclick=()=>setAdvancedOpen(false);$("#workspace-scrim").onclick=()=>setAdvancedOpen(false);
$("#workflow-settings-button").onclick=()=>setWorkflowOpen(!$("#workflow-drawer").classList.contains("open"));
$("#workflow-close").onclick=()=>setWorkflowOpen(false);$("#workflow-scrim").onclick=()=>setWorkflowOpen(false);
document.addEventListener("keydown",event=>{if(event.key!=="Escape")return;if($("#advanced-workspace").classList.contains("open"))setAdvancedOpen(false);else if($("#workflow-drawer").classList.contains("open"))setWorkflowOpen(false)});
$("#task-view-button").onclick=()=>{app.view="task";render();setAdvancedOpen(true)};$("#history-view-button").onclick=()=>{app.view="history";render();setAdvancedOpen(true)};
$("#language-button").onclick=()=>{app.lang=app.lang==="zh"?"en":"zh";localStorage.setItem("facade_lang",app.lang);render()};
async function submitAgentMessage(text){addMessage("user",text);const form=$("#agent-form"),currentConversationId=app.project?.project_id||"__global__";form.classList.add("busy");try{const selected=app.images[app.imageIndex]?.image_id||null;const data=await api("/api/agent/chat",{method:"POST",body:JSON.stringify({text,project_id:app.project?.project_id||null,selected_image_id:selected})});addMessage("agent",data.result.message);if(data.result.status==="awaiting_human_confirmation"){const pending=data.result.pending;app.pendingAgentId=pending.pending_id;$("#confirm-title").textContent=`${t("tool_proposal")}: ${pending.tool_name}`;$("#confirm-copy").textContent=JSON.stringify(pending.arguments,null,2);$("#confirm-dialog").showModal()}else if(data.result.action==="open_project_creation"){app.projectDraft=data.result.project_draft||null;app.view="task";renderWorkspace();setAdvancedOpen(true)}else if(data.result.navigation){app.view="task";await refresh(currentConversationId);setAdvancedOpen(true)}else{await refresh(currentConversationId)}}catch(error){addMessage("agent",`${app.lang==="zh"?"模型调用失败":"Model call failed"}: ${error.message}`)}finally{form.classList.remove("busy")}}
async function resolveAgentConfirmation(pendingId,approved){try{const data=await api("/api/agent/confirm",{method:"POST",body:JSON.stringify({pending_id:pendingId,approved,actor_id:"local_engineer"})});addMessage("agent",data.result.message);await refresh(app.project?.project_id||null)}catch(error){addMessage("agent",`${app.lang==="zh"?"确认操作失败":"Confirmation failed"}: ${error.message}`)}}
function environmentBytes(value){if(value===null||value===undefined)return "—";return formatBytes(value)}
function renderEnvironmentSummary(){const target=$("#environment-summary"),data=app.environment;if(!data){target.innerHTML=`<div class="empty">${t("detecting_environment")}</div>`;return}const inv=data.inventory,caps=inv.capabilities,gpus=inv.nvidia.gpus||[],selected=data.settings.gpu_devices?.[0]??gpus[0]?.index;const capability=(label,ready)=>`<div class="environment-cap ${ready?"ready":"missing"}"><span>${esc(label)}</span><strong>${ready?t("ready"):t("unavailable")}</strong></div>`;target.innerHTML=`<div class="environment-caps">${capability(t("interface_ready"),caps.interface_ready)}${capability(t("gpu_training"),caps.local_gpu_training_ready)}</div><div class="environment-facts"><span>${esc(inv.platform.system)} ${esc(inv.platform.release)}</span><span>Python ${esc(inv.python.version)}</span><span>${t("memory_label")}: ${environmentBytes(inv.memory.total_bytes)}</span><span>${t("disk_free")}: ${environmentBytes(inv.disk.free_bytes)}</span><span>${t("effective_mode")}: ${esc(data.settings.effective_mode)}</span><span>${t("selected_gpus")}: ${selected===undefined?"—":`GPU ${selected}`}</span></div>${inv.warnings.length?`<div class="notice">${inv.warnings.map(esc).join("<br>")}</div>`:""}<div class="notice">${app.lang==="zh"?"运行时会自动检测环境；本版本只使用一张 GPU。缺少依赖时需要工程师明确确认后才会安装。":"The runtime detects prerequisites automatically; this release uses one GPU. Missing dependencies are installed only after explicit engineer confirmation."}</div>`;$("#compute-mode").value=data.settings.configured_mode;$("#cpu-threads").value=data.settings.cpu_threads;$("#cpu-threads").max=inv.cpu.logical_cores;$("#gpu-device-list").innerHTML=""}
async function openEnvironmentSettings(){$("#environment-dialog").showModal();app.environment=null;renderEnvironmentSummary();try{app.environment=(await api("/api/environment/status")).environment;renderEnvironmentSummary()}catch(error){$("#environment-summary").innerHTML=`<div class="notice error">${esc(error.message)}</div>`}}
async function saveEnvironment(event){event.preventDefault();try{app.environment=(await api("/api/environment/configure",{method:"POST",body:JSON.stringify({mode:$("#compute-mode").value,gpu_devices:[],cpu_threads:Number($("#cpu-threads").value||0)})})).environment;$("#environment-dialog").close();toast(t("environment_saved"))}catch(error){toast(error.message)}}
$("#environment-button").onclick=openEnvironmentSettings;$("#environment-cancel").onclick=()=>$("#environment-dialog").close();$("#environment-form").onsubmit=saveEnvironment;$("#environment-bootstrap").onclick=async()=>{if(!confirm(app.lang==="zh"?"确认准备运行环境？这会安装锁定依赖并下载预训练权重。":"Prepare the runtime now? This installs locked dependencies and downloads pretrained weights."))return;const button=$("#environment-bootstrap");button.disabled=true;try{app.environment=(await api("/api/environment/bootstrap",{method:"POST",body:JSON.stringify({confirmed:true})})).environment;renderEnvironmentSummary();toast(app.lang==="zh"?"运行环境准备完成":"Runtime setup completed")}catch(error){toast(error.message)}finally{button.disabled=false}};
function selectedLlmPreset(){return app.llmPresets.find(item=>item.id===$("#llm-provider").value)}
function collectLlmValues(){return {mode:$("#llm-mode").value,provider:$("#llm-provider").value,base_url:$("#llm-base-url").value.trim(),model:$("#llm-model").value.trim(),api_key:$("#llm-api-key").value,protocol:$("#llm-protocol").value}}
function invalidateLlmVerification(changed=true){app.llmVerificationToken="";$("#llm-connect").disabled=$("#llm-mode").value!=="disabled";const state=$("#llm-verification");state.className="connection-state";state.textContent=t(changed?"connection_changed":"connection_untested")}
function applyLlmPreset(fillValues=true){const disabled=$("#llm-mode").value==="disabled",preset=selectedLlmPreset();if(preset&&fillValues){$("#llm-base-url").value=preset.base_url;$("#llm-protocol").value=preset.protocol;$("#llm-model").placeholder=preset.model_example||"your-model-id"}$("#llm-provider").disabled=disabled;$("#llm-base-url").disabled=disabled||Boolean(preset?.base_url_locked);$("#llm-model").disabled=disabled;$("#llm-api-key").disabled=disabled;$("#llm-protocol").disabled=disabled||Boolean(preset?.base_url_locked);$("#llm-test").disabled=disabled;$("#llm-connect").disabled=!disabled&&!app.llmVerificationToken;if(disabled){$("#llm-verification").textContent=t("llm_disabled");$("#llm-verification").className="connection-state"}}
async function openLlmSettings(){if(!app.llmPresets.length)app.llmPresets=(await api("/api/llm/presets")).presets;$("#llm-provider").innerHTML=app.llmPresets.map(item=>`<option value="${esc(item.id)}">${esc(item.label)}</option>`).join("");const cfg=app.llm;$("#llm-mode").value=cfg.mode||"disabled";$("#llm-provider").value=app.llmPresets.some(item=>item.id===cfg.provider)?cfg.provider:"custom";$("#llm-base-url").value=cfg.base_url||"";$("#llm-model").value=cfg.model||"";$("#llm-api-key").value="";$("#llm-protocol").value=cfg.protocol||"responses";invalidateLlmVerification(false);applyLlmPreset(false);$("#llm-dialog").showModal()}
$("#llm-mode").onchange=()=>{invalidateLlmVerification();applyLlmPreset(false)};
$("#llm-provider").onchange=()=>{invalidateLlmVerification();applyLlmPreset(true)};
["#llm-base-url","#llm-model","#llm-api-key","#llm-protocol"].forEach(selector=>$(selector).addEventListener("input",()=>invalidateLlmVerification()));
$("#llm-test").onclick=async()=>{const button=$("#llm-test");button.disabled=true;button.textContent=t("testing_connection");try{const result=await api("/api/llm/test",{method:"POST",body:JSON.stringify(collectLlmValues())});app.llmVerificationToken=result.verification_token;const state=$("#llm-verification");state.textContent=t("connection_verified");state.className="connection-state verified";$("#llm-connect").disabled=false}catch(error){invalidateLlmVerification(false);toast(error.message)}finally{button.textContent=t("test_connection");applyLlmPreset(false)}};
$("#llm-settings-button").onclick=()=>openLlmSettings().catch(error=>toast(error.message));$("#llm-cancel").onclick=()=>$("#llm-dialog").close();$("#llm-form").onsubmit=async event=>{event.preventDefault();try{const data=await api("/api/llm/configure",{method:"POST",body:JSON.stringify({...collectLlmValues(),verification_token:app.llmVerificationToken})});app.llm=data.llm;app.llmVerificationToken="";$("#llm-api-key").value="";$("#llm-dialog").close();renderAgent();toast(app.llm.verified?t("llm_verified"):t("llm_disabled"))}catch(error){toast(error.message)}};
$("#verify-audit").onclick=async()=>{try{const result=(await api("/api/audit/verify")).audit_chain;$("#audit-indicator").className=result.valid?"audit-good":"audit-bad";toast(result.valid?t("audit_valid"):t("audit_invalid"))}catch(error){toast(error.message)}};
$("#agent-form").onsubmit=event=>{event.preventDefault();const input=$("#agent-input"),text=input.value.trim();if(!text)return;input.value="";submitAgentMessage(text)};
const phase4fHistoryDescriptionBase=historyDescription;
historyDescription=function(item){const d=item.data;if(item.kind==="evaluation_job")return {title:`${t("evaluation_jobs_count")} · ${d.job_id}`,body:`${d.status} · ${d.evaluation_profile_id}`,code:d.bundle_sha256?.slice(0,16)};if(item.kind==="evaluation_gate")return {title:`${t("evaluation_gates_count")} · ${d.gate_key}`,body:`${d.role} · ${d.status} · ${d.image_count} ${t("images")}`,code:d.content_sha256?.slice(0,16)};if(item.kind==="evaluation_run")return {title:`${t("evaluation_runs_count")} · ${d.run_id}`,body:`${d.status} · GPU ${(d.gpu_devices||[]).join(",")||"—"}`,code:d.result_bundle_sha256?.slice(0,16)};if(item.kind==="evidence")return {title:`${t("evidence_reports_count")} · ${d.evidence_id}`,body:`${d.champion_model_id} → ${d.challenger_model_id}`,code:d.artifact_sha256?.slice(0,16)};if(item.kind==="decision")return {title:`${t("deployment_decisions_count")} · ${d.decision}`,body:d.reason,code:d.decision_id};return phase4fHistoryDescriptionBase(item)};
