Object.assign(copy.en,{evaluation_intro:"This round evaluates a fresh Current Gate and adds it to cumulative Core Safety.",evaluation_inbox_empty:"Place the independent evaluation ZIP in the evaluation inbox shown by this application.",create_evaluation_confirmation:"Confirm importing this round's Current Gate. Checksums, taxonomy, labels, and zero overlap are verified; the backend assembles cumulative Core Safety.",start_evaluation_confirmation:"Confirm evaluating the fresh Current Gate together with cumulative Core Safety. No model is selected or deployed automatically.",current_gate:"Current Gate",historical_gates:"Core Safety",gate_history:"Cumulative Core Safety history",deploy:"Promote Challenger",hold:"Retain Champion",decision_confirmation:"Confirm the single terminal decision for this round. Promote switches Active Champion; Retain keeps the current Champion.",decision_reason_placeholder:"Explain why the Challenger should be promoted, or why the current Champion should be retained"});
const renderChallengerTrainedBase=renderChallengerTrained;
renderChallengerTrained=function(model){renderChallengerTrainedBase(model);const panel=roundCompletionPanel();if(panel){const target=$("#workspace-content");target.insertAdjacentHTML("beforeend",panel)}};
refresh().catch(error=>{$("#workspace-content").innerHTML=`<div class="notice error">${esc(error.message)}</div>`});
